"""Format schema-scoped memory entries for the active-skill system prompt.

Pure transform: callers pass the skill's ``MemoryManager.read_all`` result
(already scoped to public/private/project visibility). This module never reads
the tracker or re-applies visibility rules.
"""

from __future__ import annotations

import json
from typing import Any, Mapping

from rasa.mantle.memory.field import MemoryEntry
from rasa.mantle.memory.manager import PROJECT_NAMESPACE

MAX_MEMORY_VALUE_LENGTH = 100
"""Soft cap on a single rendered memory value in the system prompt."""

TRUNCATION_SUFFIX = "... [truncated]"
"""Marker appended when a rendered value exceeds :data:`MAX_MEMORY_VALUE_LENGTH`."""

PII_SET_PLACEHOLDER = "[set]"
"""Placeholder for set ``field.pii`` entries (value exists, content withheld)."""


def format_memory_prompt_lines(entries: Mapping[str, MemoryEntry]) -> tuple[str, ...]:
    """Render set memory entries as ``<key>: <value>`` lines for the system prompt.

    Args:
        entries: Fully-qualified slot name → :class:`MemoryEntry` from
            ``MemoryManager.read_all`` (e.g. ``order_status.orders_summary``).

    Returns:
        Prompt lines for the ``### Memory:`` section. Unset (``None``)
        values are omitted. Set ``field.pii`` entries appear as
        ``<key>: [set]`` without the raw value. Keys use the fully-qualified
        slot name from ``read_all`` (e.g. ``order_status.orders_summary``).
    """
    lines: list[str] = []
    for slot_name, entry in entries.items():
        if entry.value is None:
            continue
        if entry.field.pii:
            lines.append(f"{slot_name}: {PII_SET_PLACEHOLDER}")
            continue
        rendered = render_memory_value(entry.value)
        lines.append(f"{slot_name}: {rendered}")
    return tuple(lines)


def skipped_collect_display_value(entry: MemoryEntry) -> str:
    """Prompt-safe value for a skipped-collect notice.

    PII fields use :data:`PII_SET_PLACEHOLDER`; others use
    :func:`render_memory_value`.
    """
    if entry.field.pii:
        return PII_SET_PLACEHOLDER
    return render_memory_value(entry.value)


def partition_prompt_memory_entries(
    entries: Mapping[str, MemoryEntry],
) -> tuple[dict[str, MemoryEntry], dict[str, MemoryEntry]]:
    """Split *entries* into ``(project, skill)`` maps by slot-name prefix."""
    project_prefix = f"{PROJECT_NAMESPACE}."
    project: dict[str, MemoryEntry] = {}
    skill: dict[str, MemoryEntry] = {}
    for slot_name, entry in entries.items():
        if slot_name.startswith(project_prefix):
            project[slot_name] = entry
        else:
            skill[slot_name] = entry
    return project, skill


def render_memory_value(value: Any) -> str:
    """Serialize a memory value for LLM-facing prompt text.

    Shared by the ``### Memory:`` section and ``@memory`` prose substitution.
    Callers that need PII redaction must substitute
    :data:`PII_SET_PLACEHOLDER` before calling this helper — it does not
    inspect field metadata.

    Newlines and other runs of whitespace are collapsed so a multi-line value
    cannot break prompt bullet lists. Long values are soft-capped at
    :data:`MAX_MEMORY_VALUE_LENGTH`.
    """
    if isinstance(value, str):
        text = value
    elif isinstance(value, (bool, int, float)):
        text = str(value)
    else:
        try:
            text = json.dumps(value, default=str)
        except (TypeError, ValueError):
            text = str(value)

    text = " ".join(text.split())
    if len(text) > MAX_MEMORY_VALUE_LENGTH:
        return text[:MAX_MEMORY_VALUE_LENGTH] + TRUNCATION_SUFFIX
    return text
